      '<div class="dr-total"><span>جمع سبد خرید (' + fa(G.cartCount()) + ' کالا)</span><b>' + money(sub) + '</b></div>' +
      (off ? '<div class="dr-total" style="color:var(--ok);font-size:11.5px"><span>سود شما از این خرید</span><b style="font-size:12.5px;color:var(--ok)">' + money(off) + '</b></div>' : '') +
      '<a href="#/cart" class="btn btn--dark btn--block" data-close>مشاهده سبد خرید</a>';
    body.querySelectorAll('[data-inc]').forEach(function (b) {
      b.addEventListener('click', function () { var id = +b.getAttribute('data-inc'); var l = state.cart.find(function (x) { return x.id === id; }); G.setQty(id, (l ? l.qty : 0) + 1); });
    });
    body.querySelectorAll('[data-dec]').forEach(function (b) {
      b.addEventListener('click', function () { var id = +b.getAttribute('data-dec'); var l = state.cart.find(function (x) { return x.id === id; }); G.setQty(id, (l ? l.qty : 0) - 1); });
    });
